package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.Host.HostException (generated by CSharpToJava converter). */
public class HostException extends RuntimeException {
    private int hresult;
    public HostException() { super(); }
    public HostException(String message) { super(message); }
    public HostException(String message, Throwable cause) { super(message, cause); }

    public int getHResult() { return hresult; }
    public void setHResult(int value) { this.hresult = value; }
}
